#!/bin/bash
# 722 (Fri 27 Nov 2026 08:30, Peter by voice: "I wanted speed on all of the data ... you haven't even mentioned cricket, golf,
# horse racing. Where is the speed, the urgency to get this up and running?"). Two lanes run side by side (memory allows two),
# each sport its own session: lane 1 racing then golf; lane 2 tennis then cricket. Plus a read-only readiness check so a yes at
# the proof gate is not followed by a build delay. Trial/paper only. No orders. Nothing deleted.
B=/root/pe-builder; mkdir -p /root/pe-sports/sports $B/runs
common='HARD RULES (read /root/pe-builder/BRIEF_league.md first; all of it applies, with STANDING RULE 708): paper and trial only; never an order endpoint; nothing deleted; back up before editing; credentials only through /root/pe-queue/runner/creds.py; exchanges only; backs first, no lay at 5.0 or longer; no purchases, no sign-ups, no new accounts - use only feeds and logins this server already has and public pages whose terms allow reading. Do not write any wait check of the form pgrep -f run_scorecard.sh. MEMORY: 18 GB server shared with the recorders, the trial loop (3.4 GB a cycle) and one other session like you: database-side work in chunks, one day of ticks at a time, never more than about 5 GB yourself, check free memory before each big step. Work in /root/pe-sports/sports/<sport> (new files, schema named after the sport); read anything; do not edit /root/pe-sports/grid, the paper trader, trial.py or the goal signal - to put a rule on the trial list use the documented way session 19 and 24 did (grid.trial_rules, frozen as measured) and say what you added. METHOD, the same for every sport and already agreed with Peter: bring no rules. (1) INVENTORY what we hold and record for this sport on all three exchanges - every market type offered against recorded, prices, results, and every fact (free or already paid) - and START RECORDING what is missing today (a recorder or collector of your own in /root/pe-mechanic/watch.list; do not touch the existing recorders during live events). (2) THE MAP: how often it happened against what the price said, every market, every moment before the start and in play by the clock or the score state, three periods, counted against chance (reuse /root/pe-sports/map code and its tables; extend, do not redo what the_map.md already measured - say what it already covers). (3) THE FACTS IN PLAY: join the live state of the event (see the sport lines) as known at that moment with its measured delay, and measure whether the price already holds it. (4) REAL PRICES: for every gap that survives, the result of taking the price actually on offer on our recorded days, as a BET held and as a TRADE with a target, a stop as a percentage of the stake and a time limit, with the in-play bet delay modelled; both halves of the dates; worst day; without the best day. (5) Rule 708: the opposite side, every other market of the event, the other exchanges, before any bad number. (6) What survives goes on the TRIAL list, frozen as measured. REPORT /root/pe-queue/reports/sport_<sport>.md, plain English, one screen: line 1 = what we now record for this sport and what was added today; line 2 = how many gaps survive and £ a day at £40 for the best non-overlapping set at real prices; line 3 = what went on trial; then the survivors as sentences a non-trader can read; then what could not be measured and the ONE thing missing for each. Start with what the data supports. Push a first version within 4 hours and again at the end: cd /root/pe-queue && git add reports/sport_<sport>.md && git commit -qm "<sport>: recorded, map, facts, trial" && git pull -q --no-rebase --no-edit && env -u GITHUB_TOKEN git push -q. Then end the session.'
mk(){ # name, sport-specific lines
cat > $B/BRIEF_sport_$1.md <<EOF
You are a Builder on Peter Edwards' trading server: the $1 session, started 27 Nov 2026 on Peter's order for speed on every sport.
SPORT: $1. $2
$common
EOF
sed -i "s/<sport>/$1/g" $B/BRIEF_sport_$1.md
cat > $B/run_sport_$1.sh <<SH
#!/bin/bash
CL=\$(cat /root/pe-watchman/claude_path); ts=\$(date -u +%F_%H%M); mkdir -p /root/pe-sports/sports/$1
cd /root/pe-sports/sports/$1 && timeout -k 60 28800 "\$CL" -p "\$(cat $B/BRIEF_sport_$1.md)" --allowedTools "Bash,Read,Write,Edit,Glob,Grep" --max-turns 700 --output-format text > $B/runs/\${ts}_sport_$1.log 2>&1
echo "sport $1 session ended \$(date -u '+%F %H:%M') exit \$?" >> $B/sessions.log
SH
chmod +x $B/run_sport_$1.sh; }
mk racing "British and Irish horse racing first, then greyhounds if time. What the_map.md already found: win and place prices are right at the starting price and 2 minutes before; long shots are no gap. NOT yet done: (a) in running - the map had only one-minute prints; use our stream ticks (one second) for every race recorded: by distance, field size, going, race type, position in the betting, and how the price is moving, with the one-second bet delay; (b) BETFAIR STARTING PRICE, an idea raised 21 Nov and never run: getting in or out at the starting price costs commission only, no gap between back and lay - measure every way of using it: take a price before the off and close at the starting price; enter at the starting price and close in running or hold; the near and far projected prices before the off against the final starting price (are they predictable; who is on the other side); (c) the facts restarted on 21 Nov (racecards, draw, jockey, trainer, going, form) joined before the off and in running, including draw by course and distance; (d) the other racing markets recorded since 21 Nov (place, other place terms, forecast, without the favourite, match bets) against the win market; (e) Ireland, and overseas racing Betfair offers (USA, Australia, South Africa, France) - record and map them, they are thinner."
mk golf "Golf was NOT loaded into the map at all - start there: load every golf result and price we hold (the history files have golf Jan 2020 to Apr 2026; leaderboards were collected) and map outright winner, top 5/10/20, make the cut, round leader, match bets and three-balls: before the tournament, after each round, and in running by leaderboard position and strokes behind. Facts: world ranking, recent form, course history, tee time and weather where free. Golf prices move slowly over four days, which suits a small trader: measure back-before-the-tournament and trade-out-after-round-one-or-two properly, with real prices where recorded."
mk tennis "Hindsight said 42% of all available in-play money was in tennis, and we trade it blind: no point-by-point score. FIRST find a score feed we are allowed to use without buying or signing up: Betfair's own in-play scores service for the events we hold a session for is the first place to look (read-only, same login the recorder uses; check the terms in the API documentation the recorder's code references); then any free public feed; measure its delay against Betfair's price jumps. If none, rebuild the score from the price path itself (breaks and holds show as jumps) and say how reliable that is against a sample checked by hand. Then the map in play by set, game and point state where known (serving or receiving, break point, set point, after a break, after losing the first set), by tour, round, surface, ranking gap and best of 3 or 5; every market Betfair offers (match odds, set betting, set winner, game markets, handicaps, totals) recorded from today. The known trader ideas are only there as things the map will confirm or kill, not as a starting list."
mk cricket "The ball-by-ball feed stopped on 21 Oct: find why, restart it or replace it from a free permitted source, and measure its delay against Betfair's price moves (Betfair's own in-play scores service first, as for tennis). Then the map in play by format (Test, one-day, T20), innings, over, runs, wickets in hand, required rate, and who is batting, for match odds, innings runs lines, session markets and any others Betfair offers - record the missing ones from today. Cricket prices swing hard on wickets and are thinly traded outside the big leagues: measure whether the price over- or under-reacts to a wicket, a big over, and the powerplay, at real prices with the bet delay."
cat > $B/BRIEF_ready.md <<'EOF'
You are a Builder on Peter Edwards' trading server: a READ-ONLY readiness check. Change nothing. Never call an order endpoint; do not run the order program; do not touch /root/REAL_MONEY_OFF (confirm it exists and say so). Read /root/pe-builder/BRIEF_league.md first.
WHY: one trial rule (T1: back the favourite in football match-result markets with under £5,000 matched, two minutes before the start, held to the result) is due to reach the paper bar about 1 Dec, then the proof gate (100 settled paper bets, profit overall and in each half, then Peter's yes), then real £2 bets. Peter wants no delay between his yes and the first order. On 20 Nov the chat promised a dry run of the real-order path and never did it.
REPORT /root/pe-queue/reports/ready_for_real.md, plain English, one screen: (1) what on this server can place a real Betfair order today (which program, when it last placed one, what stops it now - list every switch, flag and limit, including Peter's £50 a bet limit and where it is enforced); (2) exactly what T1 needs that the program does not do yet (market selection by matched money two minutes before the start, stake sizing at £2, one bet per match, the daily and bank limits from the bank book, logging each order beside its paper twin so real fills can be compared with paper); (3) the risks specific to this rule with real money (thin markets under £5,000: will £2, £10, £25, £50 actually be matched at the price - measure from our recorded book how much was on offer at the best price two minutes before the start in these markets, as a table by stake); (4) a numbered build list to be ready, with hours for each, and what can be tested without placing anything; (5) how the real fills would be reconciled to paper daily. Do not build any of it - list it. Commit and push: cd /root/pe-queue && git add reports/ready_for_real.md && git commit -qm "readiness check for the first real orders (read-only)" && git pull -q --no-rebase --no-edit && env -u GITHUB_TOKEN git push -q. Then end the session.
EOF
cat > $B/run_ready.sh <<'SH'
#!/bin/bash
CL=$(cat /root/pe-watchman/claude_path); ts=$(date -u +%F_%H%M)
cd /root && timeout -k 60 5400 "$CL" -p "$(cat /root/pe-builder/BRIEF_ready.md)" --allowedTools "Bash,Read,Glob,Grep,Write" --max-turns 120 --output-format text > /root/pe-builder/runs/${ts}_ready.log 2>&1
echo "ready session ended $(date -u '+%F %H:%M') exit $?" >> /root/pe-builder/sessions.log
SH
chmod +x $B/run_ready.sh
cat > $B/run_lane1_722.sh <<'SH'
#!/bin/bash
/root/pe-builder/run_ready.sh
/root/pe-builder/run_sport_racing.sh
/root/pe-builder/run_sport_golf.sh
SH
cat > $B/run_lane2_722.sh <<'SH'
#!/bin/bash
/root/pe-builder/run_sport_tennis.sh
/root/pe-builder/run_sport_cricket.sh
SH
chmod +x $B/run_lane1_722.sh $B/run_lane2_722.sh
nohup setsid $B/run_lane1_722.sh > /dev/null 2>&1 < /dev/null &
nohup setsid $B/run_lane2_722.sh > /dev/null 2>&1 < /dev/null &
sleep 20
echo "lane 1 (readiness, racing, golf): $(pgrep -fc '[r]un_lane1_722.sh') | lane 2 (tennis, cricket): $(pgrep -fc '[r]un_lane2_722.sh') | loader fixer: $(pgrep -fc '[r]un_fixer_loader.sh') | free memory: $(free -g | awk '/Mem/{print $7" GB of "$2}') | $(date -u +%H:%M) UTC 27 Nov" > /root/pe-queue/reports/running_now.md
cd /root/pe-queue && git add reports/running_now.md && git commit -qm "running now" -q && git pull -q --no-rebase --no-edit && env -u GITHUB_TOKEN git push -q
